Lemma u8arr_writeN : forall (m : mem) A bs (k : Z) (ws : list byte), u8arr asegs m A bs -> 0 <= k -> (Z.to_nat k + length ws <= length bs)%nat ->
  u8arr asegs (write_to_mem m (wa (A + k)) ws) A (upd_bytes bs (Z.to_nat k) ws).
Proof.
