(* [comment removed for export] *)
Ltac shbr_x2 :=
  lazymatch goal with
  | |- evt ?segs ?Q (MS ?R ?F (if ?c then Z_to_bv 64 ?SLOW else Z_to_bv 64 ?FAST) ?fc ?rv ?m ?ro) =>
      let b := shbyte_of c in
      lazymatch goal with
      | K : shk m b ?X |- _ =>
          let KY := fresh "SHKY" in let LX := fresh "LX2" in
          pose proof (lxor2_eq X ltac:(lia) ltac:(Z.div_mod_to_equations; lia)) as LX;
          assert (KY : shk m b (Z.lxor X 2))
            by (unfold shk, shad in *; replace (Z.lxor X 2 / 8) with (X / 8) by (rewrite LX; Z.div_mod_to_equations; lia); exact K);
          clear K; shbr
      end
  end.

(* [comment removed for export] *)
Definition rb2_words_exit (sp gp tp t0 t1 t2 t3 s0 s1 a0 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s9 t5end : word) (F : bvmap 5 word) (fc : bv 32) (m : mem)
    (lines lined nw datad rsd : Z) : machine_state -> Prop :=
  fun ms' => exists (ra' a2' a3' s8' s10' : word) (m' : mem) (dbs' : list byte),
    ms' = MS (mkR ra' sp gp tp t0 t1 t2 s0 s1 a0 (Z_to_bv 64 (lines + 4 * nw)) a2' a3' a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8' s9 s10' (Z_to_bv 64 SHB) t3 (Z_to_bv 64 0) (Z_to_bv 64 (lines + 4 * nw)) (Z_to_bv 64 (lined + 2 * nw)))
             F (Z_to_bv 64 0x15e9cc) fc None m' (seg_rom asegs)
    /\ munch [(datad, datad + rsd)] m m' /\ wmono asegs m m' /\ mem_inv asegs m' /\ u8arr asegs m' datad dbs' /\ Z.of_nat (length dbs') = rsd.

Lemma rb2_words : forall (k : nat) (j : Z)
    (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 t3 t4 t5 t6 : word) F fc (m : mem)
    (datas ns lines wpls nw tab datad rsd lined : Z) (sbs : list byte) (tbs : list byte) (dbs : list byte),
  a1 = Z_to_bv 64 (lines + 4 * j) -> t5 = Z_to_bv 64 (lines + 4 * j) -> t6 = Z_to_bv 64 (lined + 2 * j) -> t4 = Z_to_bv 64 (nw - j) ->
  t2 = Z_to_bv 64 (4 * wpls) -> a0 = Z_to_bv 64 tab -> a7 = Z_to_bv 64 0xffffffffaaaaaaaa ->
  Z.of_nat k = nw - j -> 0 <= j -> (1 <= k)%nat ->
  datas <= lines -> lines mod 4 = 0 -> lines + 4 * wpls + 4 * nw <= datas + ns -> 0 <= wpls -> 0 < datas -> datas mod 8 = 0 -> datas + ns <= 2^47 ->
  (datas + ns <= 0x7fff7000 \/ 0x10007fff8000 <= datas) ->
  bytes_at asegs m datas sbs -> Z.of_nat (length sbs) = ns -> acc asegs m datas ns ->
  0 < tab -> tab mod 16 = 0 -> tab + 256 <= 2^47 -> (tab + 256 <= 0x7fff7000 \/ 0x10007fff8000 <= tab) ->
  bytes_at asegs m tab tbs -> Z.of_nat (length tbs) = 256 -> acc asegs m tab 256 ->
  datad <= lined -> lined mod 4 = 0 -> lined + 2 * nw + 2 * (nw mod 2) <= datad + rsd -> 0 < datad -> datad mod 8 = 0 -> datad + rsd <= 2^47 ->
  (datad + rsd <= 0x7fff7000 \/ 0x10007fff8000 <= datad) ->
  u8arr asegs m datad dbs -> Z.of_nat (length dbs) = rsd -> acc asegs m datad rsd ->
  (datas + ns <= datad \/ datad + rsd <= datas) -> (tab + 256 <= datad \/ datad + rsd <= tab) ->
  mem_inv asegs m ->
  evt asegs (rb2_words_exit sp gp tp t0 t1 t2 t3 s0 s1 a0 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s9 t5 F fc m lines lined nw datad rsd)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7
             s2 s3 s4 s5 s6 s7 s8 s9 s10 (Z_to_bv 64 SHB) t3 t4 t5 t6)
        F (Z_to_bv 64 0x15e914) fc None m (seg_rom asegs)).
Proof.
